 private Entity RegularTarget(Entity owner,Entity source,bool vehicleOnly){
  if(!EntityManager.HasComponent<TrafficLightData>(source))return Entity.Null;
  int type=(int)EntityManager.GetComponentData<TrafficLightData>(source).m_Type&15;if(vehicleOnly)type&=3;
  var prefabs=World.GetExistingSystemManaged<PrefabSystem>();string theme="";
  if(EntityManager.HasBuffer<Game.Objects.SubObject>(owner))foreach(var item in EntityManager.GetBuffer<Game.Objects.SubObject>(owner,true)){var e=item.m_SubObject;if(!EntityManager.HasComponent<PrefabRef>(e))continue;if(prefabs.TryGetPrefab<StaticObjectPrefab>(EntityManager.GetComponentData<PrefabRef>(e).m_Prefab,out var p)&&(p.name.StartsWith("NA_")||p.name.StartsWith("EU_"))){theme=p.name.Substring(0,3);break;}}
  Entity candidate=Entity.Null;string candidateName="";int best=-1;
  foreach(var name in SourceNames.All){if(!Catalog.Entries.TryGetValue(name,out var e)||!EntityManager.HasComponent<TrafficLightData>(e)||((int)EntityManager.GetComponentData<TrafficLightData>(e).m_Type&15)!=type)continue;int score=name.StartsWith(theme)&&theme.Length>0?2:0;
if(score>best){candidate=e;candidateName=name;best=score;}}
  if(candidate==Entity.Null)return Entity.Null;
  string choice=Mod.Settings.Selection(candidateName);if(string.IsNullOrEmpty(choice)||!Catalog.Entries.TryGetValue(choice,out var selected)||!EntityManager.HasComponent<TrafficLightData>(selected)||(((int)EntityManager.GetComponentData<TrafficLightData>(selected).m_Type&12)==0)!=((type&12)==0))return Entity.Null;candidate=selected;
  return World.GetExistingSystemManaged<OverrideSystem>().RegularProxy(candidate);
 }
