 protected override void OnUpdate(){using(RuntimeDiagnostics.Measure("ApproachSignalSystem.OnUpdate")){if(_saving)return;bool on=_ready&&Mod.Settings!=null&&Mod.Settings.Enabled;if(!on){if(_active){Clear();World.GetExistingSystemManaged<FarSignalSystem>()?.RefreshAll();}return;}
 RefreshSelections();
