 _watch.Tick(EntityManager,Queue);
 _startup.Tick(_signals,OwnerOf,node=>{if(KoreanJunctionSystem.Selected(EntityManager,node))Queue(node);},UnityEngine.Time.realtimeSinceStartup);
 
 
 for(int i=0;i<2&&_head<_pending.Count&&SignalWorkBudget.TakeOwner();i++){var owner=_pending[_head++];_queued.Remove(owner);Rebuild(owner);World.GetExistingSystemManaged<LeftSignalSystem>()?.RefreshOwner(owner);World.GetExistingSystemManaged<FarSignalSystem>()?.RefreshOwner(owner);}if(_head==_pending.Count){_pending.Clear();_head=0;}}}
 private bool TryMovements(Entity owner,Entity source,out int movements,out bool turnOnly){
 movements=0;turnOnly=false;if(!EntityManager.HasComponent<Transform>(source)||!SignalApproach.Try(EntityManager,owner,EntityManager.GetComponentData<Transform>(source),out int road,out _))return false;
 var roads=LaneTopology.LiveRoads(EntityManager,owner);int valid=0;
 foreach(var sub in EntityManager.GetBuffer<Game.Net.SubLane>(owner,true)){var e=sub.m_SubLane;if(!UsableLane(e))continue;var lane=EntityManager.GetComponentData<Game.Net.Lane>(e);if(!LaneTopology.ConnectsLiveRoads(roads,lane)||lane.m_StartNode.GetOwnerIndex()!=road||lane.m_EndNode.GetOwnerIndex()==road)continue;
 var flags=EntityManager.GetComponentData<Game.Net.CarLane>(e).m_Flags;if((flags&(Game.Net.CarLaneFlags.Forbidden|Game.Net.CarLaneFlags.UTurnLeft|Game.Net.CarLaneFlags.UTurnRight))!=0)continue;var curve=EntityManager.GetComponentData<Game.Net.Curve>(e).m_Bezier;var start=math.normalizesafe((curve.b-curve.a).xz);var end=math.normalizesafe((curve.d-curve.c).xz);if(math.lengthsq(start)<.9f||math.lengthsq(end)<.9f)continue;valid++;movements|=MovementGeometry.Classify(flags,math.dot(start,end),start.x*end.y-start.y*end.x);}
 turnOnly=ThreeLampRules.TurnOnly(roads.Count,valid,movements);return valid>0;
 }
 private bool IsStraightLeft(Entity owner,Entity source)=>TryMovements(owner,source,out var movements,out _)&&ApproachRules.StraightLeft(movements);
