 private Entity ThreeLampTarget(Entity source,bool crossing,bool leftArrow=true){
 if(!EntityManager.HasComponent<PrefabRef>(source))return Entity.Null;var ps=World.GetExistingSystemManaged<PrefabSystem>();var prefab=EntityManager.GetComponentData<PrefabRef>(source).m_Prefab;string original=ps.TryGetPrefab<StaticObjectPrefab>(prefab,out var p)?p.name:"";string preferred=Mod.Settings.Selection(original);if(string.IsNullOrEmpty(preferred))preferred=crossing?_crosswalk:_vehicle;
 string best=null;int score=-1;foreach(var name in Catalog.Vehicles){if(!Catalog.Entries.TryGetValue(name,out var e)||!EntityManager.Exists(e)||!EntityManager.HasComponent<TrafficLightData>(e)||!EntityManager.HasComponent<ObjectData>(e))continue;int type=(int)EntityManager.GetComponentData<TrafficLightData>(e).m_Type;if(!ThreeLampRules.Compatible(type,crossing))continue;int rank=ThreeLampRules.Score(name,preferred,original,leftArrow);if(rank>score||(rank==score&&rank>=0&&string.CompareOrdinal(name,best)<0)){score=rank;best=name;}}
 return best==null?Entity.Null:World.GetExistingSystemManaged<OverrideSystem>().RegularProxy(Catalog.Entries[best]);
 }
 private bool UsableLane(Entity lane)=>Live(lane)&&!EntityManager.HasComponent<Temp>(lane)&&!EntityManager.HasComponent<Game.Net.MasterLane>(lane)&&EntityManager.HasComponent<Game.Net.Lane>(lane)&&EntityManager.HasComponent<Game.Net.CarLane>(lane)&&EntityManager.HasComponent<Game.Net.Curve>(lane);
 private void Rebuild(Entity owner){ClearTurnOnly(owner);if(!KoreanJunctionSystem.Selected(EntityManager,owner)){RemoveOwner(owner);return;}if(!Live(owner)||!EntityManager.HasBuffer<Game.Objects.SubObject>(owner)){_remove.Clear();foreach(var p in _entries)if(p.Value.Owner==owner)_remove.Add(p.Key);foreach(var e in _remove){Release(e,_entries[e]);_entries.Remove(e);}_remove.Clear();foreach(var p in _eligible)if(p.Value==owner)_remove.Add(p.Key);foreach(var e in _remove)_eligible.Remove(e);return;}
 _remove.Clear();foreach(var pair in _eligible)if(pair.Value==owner)_remove.Add(pair.Key);foreach(var e in _remove)_eligible.Remove(e);
 bool preferFour=ThreeLampRules.PreferFour(LaneTopology.LiveRoads(EntityManager,owner).Count);var manualWanted=new Dictionary<Entity,Entity>();var wanted=new Dictionary<Entity,Entity>();using(var a=EntityManager.GetBuffer<Game.Objects.SubObject>(owner,true).ToNativeArray(Allocator.Temp))foreach(var item in a){var e=item.m_SubObject;if(!Live(e)||EntityManager.HasComponent<Temp>(e)||!EntityManager.HasComponent<TrafficLight>(e)||!EntityManager.HasComponent<Transform>(e)||!EntityManager.HasComponent<PrefabRef>(e))continue;var prefab=EntityManager.GetComponentData<PrefabRef>(e).m_Prefab;if(!EntityManager.HasComponent<TrafficLightData>(prefab) )continue;
 var manual=World.GetExistingSystemManaged<IndividualSignalData>().Target(owner,e,Entity.Null,false);if(manual!=Entity.Null)manualWanted[e]=manual;
 // Four-way topology takes precedence over movement-based three-lamp selection.
 if(preferFour&&((int)EntityManager.GetComponentData<TrafficLightData>(prefab).m_Type&3)!=0){_eligible[e]=owner;bool combined=((int)EntityManager.GetComponentData<TrafficLightData>(prefab).m_Type&12)!=0;if(ApproachCatalog.Resolve(EntityManager,combined?_crosswalk:_vehicle,combined,out var four))wanted[e]=four;continue;}
 if(TryMovements(owner,e,out var movements,out var turnOnly)&&(turnOnly||ThreeLampRules.StraightOnly(movements))&&((int)EntityManager.GetComponentData<TrafficLightData>(prefab).m_Type&3)!=0){if(turnOnly)_turnOnly[e]=owner;else _straightOnly[e]=owner;_eligible.Remove(e);var three=ThreeLampTarget(e,((int)EntityManager.GetComponentData<TrafficLightData>(prefab).m_Type&12)!=0,turnOnly);if(three!=Entity.Null)wanted[e]=three;continue;}else _turnOnly.Remove(e);
 if(!Mod.Settings.UseStraightLeftAssets||((int)EntityManager.GetComponentData<TrafficLightData>(prefab).m_Type&3)==0||!IsStraightLeft(owner,e)){var regular=ConfiguredTarget(prefab);if(regular!=Entity.Null)wanted[e]=regular;continue;}
 _eligible[e]=owner;int crossing=(int)EntityManager.GetComponentData<TrafficLightData>(prefab).m_Type&12;if(!ApproachCatalog.Resolve(EntityManager,crossing==0?_vehicle:_crosswalk,crossing!=0,out var target)){target=ConfiguredTarget(prefab);if(target==Entity.Null)continue;}
 if(target!=prefab)wanted[e]=target;}
 foreach(var pick in manualWanted)if(!wanted.ContainsKey(pick.Key))wanted[pick.Key]=pick.Value;
 _remove.Clear();foreach(var pair in _entries)if(pair.Value.Owner==owner&&!wanted.ContainsKey(pair.Key))_remove.Add(pair.Key);foreach(var e in _remove){Release(e,_entries[e]);_entries.Remove(e);}
 foreach(var pair in wanted){var source=pair.Key;bool hideNear=World.GetExistingSystemManaged<IndividualSignalData>().Get(owner,source)?.nearHidden??false;var aligned=SignalAlignment.Align(EntityManager,owner,source,EntityManager.GetComponentData<Transform>(source));var target=World.GetExistingSystemManaged<IndividualSignalData>().Target(owner,source,pair.Value,false);if(_entries.TryGetValue(source,out var entry)&&Live(entry.Clone)&&entry.Prefab==target){entry.BasePrefab=pair.Value;entry.HideNear=hideNear;entry.Alignment=aligned.m_Rotation;CollectChildren(source,entry,0);continue;}if(entry!=null)Release(source,entry);
 var clone=EntityManager.CreateEntity(EntityManager.GetComponentData<ObjectData>(target).m_Archetype);EntityManager.AddComponent<ApproachVisual>(clone);EntityManager.AddComponent<KoreanSignalClone>(clone);EntityManager.AddComponentData(clone,new Owner{m_Owner=owner});EntityManager.AddComponentData(clone,new IndividualSignalLink{Source=source,Owner=owner,Far=false});EntityManager.SetComponentData(clone,new PrefabRef{m_Prefab=target});EntityManager.SetComponentData(clone,aligned);EntityManager.SetComponentData(clone,EntityManager.GetComponentData<TrafficLight>(source));if(EntityManager.HasComponent<PseudoRandomSeed>(clone)&&EntityManager.HasComponent<PseudoRandomSeed>(source))EntityManager.SetComponentData(clone,EntityManager.GetComponentData<PseudoRandomSeed>(source));World.GetExistingSystemManaged<DirectionalLightSystem>()?.Link(clone,source);_entries[source]=new Entry{Clone=clone,Owner=owner,Prefab=target,BasePrefab=pair.Value,HideNear=hideNear,Alignment=aligned.m_Rotation};CollectChildren(source,_entries[source],0);}RebuildPedestrianMerges(owner);}
 private void CollectChildren(Entity source,Entry entry,int depth){if(depth>=8||entry.Children.Count>=64||!EntityManager.HasBuffer<Game.Objects.SubObject>(source))return;foreach(var item in EntityManager.GetBuffer<Game.Objects.SubObject>(source,true)){var child=item.m_SubObject;if(!Live(child)||child==source||child==entry.Clone||entry.Children.Contains(child))continue;entry.Children.Add(child);CollectChildren(child,entry,depth+1);if(entry.Children.Count>=64)break;}}
 internal void SyncVisibility(){using(RuntimeDiagnostics.Measure("ApproachSignalSystem.SyncVisibility")){if(_saving)return;_remove.Clear();var left=World.GetExistingSystemManaged<LeftSignalSystem>();foreach(var pair in _entries){var source=pair.Key;var entry=pair.Value;var clone=entry.Clone;if(!Live(source)||!Live(entry.Owner)||!Live(clone)||!EntityManager.HasComponent<TrafficLight>(source)||!EntityManager.HasComponent<Transform>(source)||!KoreanJunctionSystem.Selected(EntityManager,entry.Owner)){if(!Live(clone)&&Live(source)&&KoreanJunctionSystem.Selected(EntityManager,entry.Owner))Queue(entry.Owner);Release(source,entry);_remove.Add(source);continue;}
 bool manualHidden=entry.HideNear&&(World.GetExistingSystemManaged<FarSignalSystem>()?.DisplayReady(source)??false);
 bool leftHidden=manualHidden||(left?.IsHiddenTarget(source)??false)||MergedPedestrianHidden(source)||(World.GetExistingSystemManaged<FarSignalSystem>()?.MergedPedestrianHidden(source)??false);
 // Batch readiness controls only source visibility, never overlay synchronization.
