 if(!manualHidden&&!SignalRenderReadiness.MainReady(EntityManager,clone)){
  if(!entry.FallbackReported){entry.FallbackReported=true;RuntimeDiagnostics.Event("Native fallback: custom mesh not ready owner="+entry.Owner+" source="+source+" clone="+clone+" target="+entry.Prefab);}
  if(entry.OwnsHidden&&!leftHidden&&EntityManager.HasComponent<Hidden>(source)){EntityManager.RemoveComponent<Hidden>(source);Mark(source);entry.OwnsHidden=false;}
  foreach(var child in entry.HiddenChildren)if(Live(child)&&EntityManager.HasComponent<Hidden>(child)){EntityManager.RemoveComponent<Hidden>(child);Mark(child);}entry.HiddenChildren.Clear();
 }else{
 entry.FallbackReported=false;
 if(!EntityManager.HasComponent<Hidden>(source)){EntityManager.AddComponent<Hidden>(source);entry.OwnsHidden=true;Mark(source);}
 foreach(var child in entry.Children)if(Live(child)&&!EntityManager.HasComponent<Hidden>(child)){EntityManager.AddComponent<Hidden>(child);entry.HiddenChildren.Add(child);Mark(child);}
 }
 bool hidden=EntityManager.HasComponent<Hidden>(clone);if(hidden!=leftHidden){if(leftHidden)EntityManager.AddComponent<Hidden>(clone);else EntityManager.RemoveComponent<Hidden>(clone);Mark(clone);}
 var t=EntityManager.GetComponentData<Transform>(source);t.m_Rotation=entry.Alignment;if(!t.Equals(EntityManager.GetComponentData<Transform>(clone))){EntityManager.SetComponentData(clone,t);if(!EntityManager.HasComponent<Updated>(clone))EntityManager.AddComponent<Updated>(clone);}var native=MergePedestrianState(entry,EntityManager.GetComponentData<TrafficLight>(source));if(native.m_GroupMask1==0)native=FarVehicleRules.VehicleState(native);var state=SignalVisualTransition.Apply(ref entry.Transition,native,World);if(!state.Equals(EntityManager.GetComponentData<TrafficLight>(clone)))EntityManager.SetComponentData(clone,state);
 World.GetExistingSystemManaged<TrafficSignSystem>()?.SyncParent(source);World.GetExistingSystemManaged<TrafficSignSystem>()?.SyncParent(clone);
 }foreach(var e in _remove){_entries.Remove(e);_eligible.Remove(e);}foreach(var entry in _entries.Values)SyncPedestrianMerge(entry);}}
